-- LeadFlow CRM – baseline schema snapshot
-- Captured read-only from Supabase project smedmzwiddhmxaznqoen on 2026-11-12.
-- This file documents the schema that ALREADY EXISTS in production. It was
-- not generated by `supabase db dump`; it was reconstructed from pg_catalog.
-- Do NOT run it against production. Use it to rebuild a fresh/dev database
-- or as a reference. All later changes go in newer, dated migration files.

-- ---------------------------------------------------------------------------
-- Schemas, sequences
-- ---------------------------------------------------------------------------
create schema if not exists private;
create sequence if not exists public.lead_code_seq;   -- last_value was 83 on 2026-11-12

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------
create table public.user_roles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  role text not null check (role = any (array['super_admin','admin','staff'])),
  created_at timestamptz default now(),
  permissions jsonb,            -- default is a JSON object of permission flags (leads_view, leads_create, leads_edit, leads_delete, ...)
  commission_rate numeric default 0 check (commission_rate >= 0 and commission_rate <= 100)
);
create unique index user_roles_single_super_admin on public.user_roles (role) where role = 'super_admin';
create unique index one_super_admin_only on public.user_roles (role) where role = 'super_admin';

create table public.leads (
  id text primary key,
  created_by uuid not null references auth.users(id) on delete cascade,
  name text not null,
  phone text not null,
  company text default '',
  owner text default '',
  stage text default 'Unverified',
  arrival date,
  birthday date,
  last_contact date,
  notes text default '',
  stage_date date,
  verified_date date,
  followup_index integer default 0,
  dropped_date date,
  drop_index integer default 0,
  noanswer integer default 0,
  completed_date date,
  created_at timestamptz default now(),
  updated_at timestamptz default now(),
  group_number text,
  documents_dispatched boolean default false,
  review_taken boolean default false,
  lead_code text,
  source text default '',
  pending_payment numeric default 0,
  payment_status text default 'not_set' check (payment_status = any (array['not_set','pending','collected'])),
  payment_collected_at date,
  payment_followup_date date,
  created_by_name text default '',
  lead_types text[] default '{}'::text[],
  whatsapp_opt_in boolean default false,
  pending_government_charges numeric default 0 check (pending_government_charges >= 0),
  pending_professional_fees numeric default 0 check (pending_professional_fees >= 0)
);
create index leads_stage_idx on public.leads (stage);
create index leads_phone_idx on public.leads (phone);
create index leads_updated_at_idx on public.leads (updated_at desc);
create unique index leads_group_number_unique on public.leads (group_number) where group_number is not null and group_number <> '';
create unique index leads_lead_code_unique on public.leads (lead_code) where lead_code is not null and lead_code <> '';

create table public.payment_collections (
  id uuid primary key default gen_random_uuid(),
  lead_id text not null references public.leads(id) on delete cascade,
  amount numeric not null check (amount > 0),
  collected_on date default current_date,
  created_by uuid references auth.users(id),
  created_at timestamptz default now(),
  created_by_name text default '',
  commission_rate numeric default 0 check (commission_rate >= 0 and commission_rate <= 100),
  commission_amount numeric default 0 check (commission_amount >= 0),
  government_charges_amount numeric default 0 check (government_charges_amount >= 0),
  professional_fees_amount numeric default 0 check (professional_fees_amount >= 0),
  payment_component text default 'legacy' check (payment_component = any (array['government_charges','professional_fees','legacy']))
);

create table public.call_activity (
  id uuid primary key default gen_random_uuid(),
  lead_id text references public.leads(id) on delete set null,
  staff_user_id uuid references auth.users(id) on delete set null,
  staff_name text default '',
  staff_email text default '',
  call_date date default current_date,
  outcome text default '',
  created_at timestamptz default now()
);

create table public.client_drive_links (
  id uuid primary key default gen_random_uuid(),
  lead_id text not null unique,
  drive_url text default '',
  updated_by uuid default auth.uid(),
  updated_at timestamptz default now()
);

create table public.client_portal_credentials (
  id uuid primary key default gen_random_uuid(),
  lead_id text not null,
  portal_name text not null,
  website_url text default '',
  login_id text default '',
  password_value text default '',      -- NOTE: stored in plain text (see audit)
  notes text default '',
  created_by uuid default auth.uid(),
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
create index client_portal_credentials_lead_id_idx on public.client_portal_credentials (lead_id);

create table public.lead_type_options (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  active boolean default true,
  sort_order integer default 0,
  created_at timestamptz default now()
);

create table public.automation_message_log (
  id uuid primary key default gen_random_uuid(),
  lead_id uuid not null,              -- NOTE: uuid here, but leads.id is text
  event_type text not null,
  scheduled_date date default current_date,
  provider_message_id text,
  status text default 'sent',
  created_at timestamptz default now(),
  unique (lead_id, event_type, scheduled_date)
);

-- ---------------------------------------------------------------------------
-- Functions
-- ---------------------------------------------------------------------------
create or replace function public.current_user_role()
returns text language sql stable set search_path to '' as $$
  select ur.role from public.user_roles ur where ur.user_id = (select auth.uid()) limit 1
$$;

create or replace function private.is_super_admin()
returns boolean language sql stable security definer set search_path to '' as $$
  select exists (select 1 from public.user_roles where user_id = (select auth.uid()) and role = 'super_admin');
$$;

create or replace function public.next_lead_code()
returns text language sql security definer set search_path to 'public' as $$
  select 'L' || nextval('public.lead_code_seq')::text;
$$;

create or replace function private.assign_initial_super_admin()
returns trigger language plpgsql security definer set search_path to '' as $$
begin
  if lower(coalesce(new.email, '')) = 'kunalahuja392@gmail.com' then
    insert into public.user_roles (user_id, role) values (new.id, 'super_admin')
    on conflict (user_id) do update set role = 'super_admin';
  end if;
  return new;
end;
$$;

create trigger assign_initial_super_admin_on_signup
  after insert on auth.users for each row execute function private.assign_initial_super_admin();

-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------
alter table public.user_roles enable row level security;
alter table public.leads enable row level security;
alter table public.payment_collections enable row level security;
alter table public.call_activity enable row level security;
alter table public.client_drive_links enable row level security;
alter table public.client_portal_credentials enable row level security;
alter table public.lead_type_options enable row level security;
alter table public.automation_message_log enable row level security;

-- user_roles (note: duplicate policy styles exist in production)
create policy "Users can view own role" on public.user_roles for select to authenticated using (user_id = (select auth.uid()));
create policy "Users can read own role" on public.user_roles for select to authenticated using (user_id = (select auth.uid()));
create policy "Super admins can view all roles" on public.user_roles for select to authenticated using ((select public.current_user_role()) = 'super_admin');
create policy "Super admins can add roles" on public.user_roles for insert to authenticated with check ((select public.current_user_role()) = 'super_admin');
create policy "Super admins can update roles" on public.user_roles for update to authenticated using ((select public.current_user_role()) = 'super_admin') with check ((select public.current_user_role()) = 'super_admin');
create policy "Super admins can delete roles" on public.user_roles for delete to authenticated using ((select public.current_user_role()) = 'super_admin');
create policy "Super admin can read all roles" on public.user_roles for select to authenticated using (private.is_super_admin());
create policy "Super admin can manage roles" on public.user_roles for all to authenticated using (private.is_super_admin()) with check (private.is_super_admin());

-- leads
create policy "Users with lead create permission can create leads" on public.leads for insert to authenticated
  with check (created_by = (select auth.uid()) and exists (select 1 from public.user_roles r where r.user_id = (select auth.uid())
    and (r.role = 'super_admin' or coalesce((r.permissions ->> 'leads_create')::boolean, false))));
create policy "Users can view own leads and admins can view all" on public.leads for select to authenticated
  using (created_by = auth.uid() or exists (select 1 from public.user_roles r where r.user_id = auth.uid() and r.role = any (array['admin','super_admin'])));
create policy "Users can edit own leads and admins can edit all" on public.leads for update to authenticated
  using ((created_by = auth.uid() or exists (select 1 from public.user_roles r where r.user_id = auth.uid() and r.role = any (array['admin','super_admin'])))
    and exists (select 1 from public.user_roles r where r.user_id = auth.uid() and (r.role = 'super_admin' or coalesce((r.permissions ->> 'leads_edit')::boolean, false))))
  with check (created_by = auth.uid() or exists (select 1 from public.user_roles r where r.user_id = auth.uid() and r.role = any (array['admin','super_admin'])));
create policy "Users can delete own leads and admins can delete all" on public.leads for delete to authenticated
  using ((created_by = auth.uid() or exists (select 1 from public.user_roles r where r.user_id = auth.uid() and r.role = any (array['admin','super_admin'])))
    and exists (select 1 from public.user_roles r where r.user_id = auth.uid() and (r.role = 'super_admin' or coalesce((r.permissions ->> 'leads_delete')::boolean, false))));

-- payment_collections (select/insert/update/delete for lead creator or admins)
create policy payment_collections_select_owned on public.payment_collections for select to authenticated
  using (exists (select 1 from public.leads l where l.id = payment_collections.lead_id and (l.created_by = auth.uid()
    or exists (select 1 from public.user_roles r where r.user_id = auth.uid() and r.role = any (array['admin','super_admin'])))));
create policy payment_collections_insert_owned on public.payment_collections for insert to authenticated
  with check (created_by = auth.uid() and exists (select 1 from public.leads l where l.id = payment_collections.lead_id and (l.created_by = auth.uid()
    or exists (select 1 from public.user_roles r where r.user_id = auth.uid() and r.role = any (array['admin','super_admin'])))));
create policy payment_collections_update_owned on public.payment_collections for update to authenticated
  using (exists (select 1 from public.leads l where l.id = payment_collections.lead_id and (l.created_by = auth.uid()
    or exists (select 1 from public.user_roles r where r.user_id = auth.uid() and r.role = any (array['admin','super_admin'])))))
  with check (exists (select 1 from public.leads l where l.id = payment_collections.lead_id and (l.created_by = auth.uid()
    or exists (select 1 from public.user_roles r where r.user_id = auth.uid() and r.role = any (array['admin','super_admin'])))));
create policy payment_collections_delete_owned on public.payment_collections for delete to authenticated
  using (exists (select 1 from public.leads l where l.id = payment_collections.lead_id and (l.created_by = auth.uid()
    or exists (select 1 from public.user_roles r where r.user_id = auth.uid() and r.role = any (array['admin','super_admin'])))));

-- call_activity
create policy call_activity_select_owned_or_admin on public.call_activity for select to authenticated
  using (staff_user_id = auth.uid() or exists (select 1 from public.user_roles r where r.user_id = auth.uid() and r.role = any (array['admin','super_admin'])));
create policy call_activity_insert_own_lead on public.call_activity for insert to authenticated
  with check (staff_user_id = auth.uid() and exists (select 1 from public.leads l where l.id = call_activity.lead_id and (l.created_by = auth.uid()
    or exists (select 1 from public.user_roles r where r.user_id = auth.uid() and r.role = any (array['admin','super_admin'])))));

