-- lead_type_options
create policy "Authenticated users can read active lead types" on public.lead_type_options for select to authenticated using (true);
create policy "Admins can manage lead types" on public.lead_type_options for all to authenticated
  using (exists (select 1 from public.user_roles ur where ur.user_id = auth.uid() and ur.role = any (array['admin','super_admin'])))
  with check (exists (select 1 from public.user_roles ur where ur.user_id = auth.uid() and ur.role = any (array['admin','super_admin'])));

-- automation_message_log
create policy "Only admins can view automation message log" on public.automation_message_log for select to authenticated
  using (exists (select 1 from public.user_roles ur where ur.user_id = auth.uid() and ur.role = any (array['admin','super_admin'])));
